def components(cells):
    # diagonal-connected components
    cs=set(cells); out=[]
    while cs:
        c=cs.pop(); st=[c]; comp=[c]
        while st:
            i,j=st.pop()
            for di,dj in ((1,1),(1,-1),(-1,1),(-1,-1)):
                p=(i+di,j+dj)
                if p in cs: cs.remove(p); st.append(p); comp.append(p)
        out.append(comp)
    return out

def f(I):
    H,W=len(I),len(I[0]); bg=I[0][0]
    O=[row[:] for row in I]
    # group non-bg cells by color, find diagonal segments (components)
    from collections import defaultdict
    cols=defaultdict(list)
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bg: cols[I[i][j]].append((i,j))
    for v,pts in cols.items():
        comps=components(pts)
        for comp in comps:
            if len(comp)<2: continue
            S=set(comp)
            # order cells along diagonal
            if all(b-a==comp.index(a) for a,b in zip(sorted(comp))) : pass
            # determine orientation
            pts=sorted(comp)
            dr=pts[1][0]-pts[0][0]; dc=pts[1][1]-pts[0][1]
            def walk(start,dr,dc):
                n=0
                i,j=start
                while True:
                    i+=dr; j+=dc
                    if not(0<=i<H and 0<=j<W): break
                    if (i,j) in S: break
                    if I[i][j]!=bg: break
                    n+=1
                return n
            cands=[]
            for endp,(sdr,sdc) in [(pts[0],(-dr,-dc)),(pts[-1],(dr,dc))]:
                cands.append(walk(endp,sdr,sdc))
            n=max(cands)
            if n<=0: continue
            # pick direction with more cells; if tie, prefer... try both endpoints, choose max
            best=cands.index(max(cands))
            start,vec=(pts[0],(-dr,-dc)) if best==0 else (pts[-1],(dr,dc))
            i,j=start; step=vec
            k=0
            while k<n:
                i+=step[0]; j+=step[1]; k+=1
                O[i][j]=v
    return O

